package com.nexttv;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import java.util.*;
/** Public accessibility/UI + real video: executes against the actual minified Release too. */
public class ViewingDesignInstrumentation extends Instrumentation {
 Activity activity;boolean inlineRecording;int passed;String tag="normal";android.content.SharedPreferences prefs;Map<String,?> saved;
 @Override public void onCreate(Bundle b){super.onCreate(b);if(b!=null){tag=b.getString("shotTag","normal");inlineRecording=Boolean.parseBoolean(b.getString("inlineRecord","false"));}start();}
 AccessibilityNodeInfo root(){AccessibilityNodeInfo n=getUiAutomation().getRootInActiveWindow();if(n!=null)n.refresh();return n;}
 String text(){return FreshAccessibilityNodes.text(root());}
 String focus(){return FreshAccessibilityNodes.text(FreshAccessibilityNodes.focused(root())).trim();}
 AccessibilityNodeInfo find(String t,AccessibilityNodeInfo n){if(n==null||!n.refresh())return null;if(t.contentEquals(n.getText()==null?"":n.getText()))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo a=find(t,n.getChild(i));if(a!=null)return a;}return null;}
 void await(String l,java.util.concurrent.Callable<Boolean> f)throws Exception{long until=SystemClock.uptimeMillis()+45000;while(SystemClock.uptimeMillis()<until){if(f.call())return;SystemClock.sleep(70);}throw new IllegalStateException(l+" focus="+focus()+" text="+text());}
 void key(int k){sendKeyDownUpSync(k);waitForIdleSync();SystemClock.sleep(160);}
 void click(String label)throws Exception{await("actionable "+label,()->{AccessibilityNodeInfo n=find(label,root());while(n!=null&&!n.isClickable())n=n.getParent();return n!=null&&n.performAction(AccessibilityNodeInfo.ACTION_CLICK);});SystemClock.sleep(300);}
 void holdOk(){sendKeySync(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_CENTER));SystemClock.sleep(800);sendKeySync(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_CENTER));SystemClock.sleep(200);}
 String dump(){java.io.StringWriter s=new java.io.StringWriter();runOnMainSync(()->activity.dump("",null,new java.io.PrintWriter(s),null));return s.toString();}
 org.json.JSONObject browser()throws Exception{java.util.regex.Matcher m=java.util.regex.Pattern.compile("NextTVBrowser (\\{[^\\n]+\\})").matcher(dump());return m.find()?new org.json.JSONObject(m.group(1)):new org.json.JSONObject();}
 AccessibilityNodeInfo rateSlot(AccessibilityNodeInfo n){if(n==null||!n.refresh())return null;if(n.getContentDescription()!=null&&n.getContentDescription().toString().startsWith("接收速率 "))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo r=rateSlot(n.getChild(i));if(r!=null)return r;}return null;}
 void rateFits()throws Exception{await("receive rate slot",()->rateSlot(root())!=null);AccessibilityNodeInfo n=rateSlot(root());Rect bounds=new Rect();n.getBoundsInScreen(bounds);android.util.DisplayMetrics metrics=getTargetContext().getResources().getDisplayMetrics();float widthDp=metrics.widthPixels/metrics.density;float viewport=Math.max(1f,Math.min(1.8f,widthDp*29f/(1920f*16f)));android.graphics.Paint paint=new android.graphics.Paint();paint.setTypeface(android.graphics.Typeface.create("sans-serif",android.graphics.Typeface.BOLD));paint.setTextSize(12f*metrics.scaledDensity*viewport);float needed=paint.measureText("888.8 MB/s");if(bounds.width()+1<needed)throw new IllegalStateException("Receive rate unit can clip width="+bounds.width()+" needed="+needed);}
 void rendered()throws Exception{await("actual first frame",()->{java.util.regex.Matcher m=java.util.regex.Pattern.compile("firstFrameMs=(\\d+)").matcher(dump());return m.find()&&Long.parseLong(m.group(1))>0;});}
 void pass(String s){passed++;Bundle b=new Bundle();b.putString("stream","PASS "+s+"\n");sendStatus(0,b);}
 void shot(String scene)throws Exception{SystemClock.sleep(250);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();ContentValues v=new ContentValues();v.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,"nexttv-1.3.37-"+tag+"-"+scene+".png");v.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"image/png");v.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Download/NextTVAudit");android.net.Uri uri=getTargetContext().getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);try(java.io.OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 void restore(){if(activity!=null)runOnMainSync(()->activity.finish());if(saved==null)return;android.content.SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,?> x:saved.entrySet()){Object v=x.getValue();if(v instanceof Boolean)e.putBoolean(x.getKey(),(Boolean)v);else if(v instanceof String)e.putString(x.getKey(),(String)v);else if(v instanceof Integer)e.putInt(x.getKey(),(Integer)v);else if(v instanceof Long)e.putLong(x.getKey(),(Long)v);else if(v instanceof Float)e.putFloat(x.getKey(),(Float)v);else if(v instanceof Set)e.putStringSet(x.getKey(),(Set<String>)v);}e.commit();}
 @Override public void onStart(){int code=Activity.RESULT_OK;String result="";try{
 prefs=getTargetContext().getSharedPreferences("nexttv",0);saved=prefs.getAll();prefs.edit().putBoolean("start_live",false).putBoolean("grid_mode",true).putBoolean("auto_update",false).putBoolean("auto_update_epg",false).remove("favorites").commit();
 activity=startActivitySync(new Intent().setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await("Channels nav",()->focus().equals("频道"));await("real channels",()->text().contains("CCTV1综合"));if(text().contains("重新拉取"))throw new IllegalStateException("Obsolete refresh button");shot("home");
 key(KeyEvent.KEYCODE_DPAD_DOWN);await("filter",()->focus().equals("分类"));key(KeyEvent.KEYCODE_DPAD_DOWN);await("first card",()->focus().contains("CCTV1综合"));holdOk();click("添加收藏");key(KeyEvent.KEYCODE_DPAD_RIGHT);holdOk();click("添加收藏");key(KeyEvent.KEYCODE_ESCAPE);await("Channels return",()->focus().equals("频道"));key(KeyEvent.KEYCODE_DPAD_RIGHT);await("Favorites",()->text().contains("我的收藏"));key(KeyEvent.KEYCODE_DPAD_DOWN);await("favourite first card",()->focus().contains("CCTV1综合"));if(text().contains("★"))throw new IllegalStateException("Redundant stars in favorites");shot("favorites");holdOk();click("取消收藏");await("neighbor after removal",()->focus().contains("CCTV2财经")&&text().contains("我的收藏"));holdOk();click("取消收藏");await("last removed returns Favorites menu",()->focus().equals("收藏")&&text().contains("还没有收藏频道"));pass("favorite grid shares card hierarchy; removal restores neighbor/empty menu and retains global channel numbers");
 key(KeyEvent.KEYCODE_DPAD_LEFT);click("CCTV1综合");rendered();key(KeyEvent.KEYCODE_INFO);rateFits();shot("player-info");pass("critical receive-rate slot fits complete units at actual window typography scale");key(KeyEvent.KEYCODE_MENU);await("quick controls",()->text().contains("解码方式")&&text().contains("音轨")&&text().contains("主页"));if(text().contains("更多"))throw new IllegalStateException("Obsolete More submenu");shot("player-quick");click("解码方式");await("actual decoder modes",()->text().contains("硬件解码")&&text().contains("软件解码"));key(KeyEvent.KEYCODE_ESCAPE);await("Back closes every overlay",()->!text().contains("更多操作")&&!text().contains("软件解码"));pass("direct quick actions, actual decoder choices and one-Back overlay dismissal");
 key(KeyEvent.KEYCODE_DPAD_CENTER);await("channel browser",()->browser().optString("region").equals("channels"));String playing=browser().getString("playing");key(KeyEvent.KEYCODE_DPAD_LEFT);await("groups",()->browser().optString("region").equals("groups"));String before=browser().getString("group");key(KeyEvent.KEYCODE_DPAD_UP);await("group previews without OK",()->!browser().optString("group").equals(before));String selected=browser().getString("group");shot("groups-preview");key(KeyEvent.KEYCODE_DPAD_RIGHT);await("Right keeps previewed group",()->browser().optString("pane").equals("channels")&&browser().optString("group").equals(selected));if(!browser().getString("playing").equals(playing))throw new IllegalStateException("Group focus changed actual channel");shot("channels");key(KeyEvent.KEYCODE_DPAD_RIGHT);await("programme pane",()->browser().optString("pane").equals("epg"));shot("programmes");key(KeyEvent.KEYCODE_ESCAPE);await("Back leaves player",()->!dump().contains("NextTVBrowser"));pass("group focus previews candidates, Right enters that group without tuning, linked EPG and Back remain correct");
 result="Viewing design: "+passed+" groups passed";
 }catch(Throwable t){code=Activity.RESULT_CANCELED;result=android.util.Log.getStackTraceString(t);try{shot("failure");}catch(Exception ignored){}}finally{restore();}Bundle b=new Bundle();b.putString("stream",result);finish(code,b);}
}
